// The sheet's furniture: the corner title block (a table the pen draws, then the cells type in) and a border rule.
import React from 'react';
import { BLUEPRINT } from './tokens.js';
import { Stroke, lineD, penFrames, rectD } from './draw.js';
import { Typed } from './type.js';

export interface Cell { label: string; value: string }

export interface TitleBlockProps {
  /** top-left corner and size in page px */
  x: number;
  y: number;
  w: number;
  h: number;
  cells: Cell[];
  cols?: number;
  at: number;
}

export const TitleBlock: React.FC<TitleBlockProps> = ({ x, y, w, h, cells, cols = 2, at }) => {
  const rows = Math.ceil(cells.length / cols);
  const cw = w / cols, rh = h / rows;
  const frame = rectD(x, y, w, h);
  const t0 = at + penFrames(frame, 'thin', 90);
  const rules: string[] = [];
  for (let c = 1; c < cols; c++) rules.push(lineD([x + c * cw, y], [x + c * cw, y + h]));
  for (let r = 1; r < rows; r++) rules.push(lineD([x, y + r * rh], [x + w, y + r * rh]));
  return (
    <>
      <Stroke d={frame} at={at} kind="object" speed={90} />
      {rules.map((d, i) => <Stroke key={i} d={d} at={t0} kind="thin" speed={110} />)}
      {cells.map((c, i) => {
        const cx = x + (i % cols) * cw + 16, cy = y + Math.floor(i / cols) * rh;
        const s = t0 + 8 + i * 4;
        return (
          <React.Fragment key={c.label}>
            <Typed text={c.label} x={cx} y={cy + rh * 0.28} size={Math.min(20, rh * 0.22)} at={s} cps={2} color={BLUEPRINT.dim} caret={false} />
            <Typed text={c.value} x={cx} y={cy + rh * 0.64} size={Math.min(40, rh * 0.38)} at={s + 3} face="label" weight={600} tracking={0.05} cps={1.2} caret={false} />
          </React.Fragment>
        );
      })}
    </>
  );
};

// The drawing: strokes put on by a pen at constant speed, dimension lines, section hatching, a grid and a callout
// circle. Everything is in page px (1080 x 1920, see PAGE) and scales with the composition. Put it all inside one
// `Ink`, which gives it the print's light: a sandy erosion of the line edge, then a halation.
import React from 'react';
import { Layer, glow, shader } from '@kinetographdev/core';
import { getLength, getPointAtLength } from '@kinetographdev/core/paths';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { BLUEPRINT, PAGE, PEN } from './tokens.js';
import { Typed } from './type.js';

export type Pt = [number, number];
export type Kind = 'object' | 'thin' | 'hatch';

const clamp01 = (t: number) => Math.min(1, Math.max(0, t));
const outCubic = (t: number) => 1 - (1 - clamp01(t)) ** 3;
const f2 = (n: number) => n.toFixed(2);

const CHALK = /* wgsl */ `
fn h21(p: vec2<f32>) -> f32 {
  let q = fract(p * vec2<f32>(0.1031, 0.1030));
  let r = q + dot(q, q.yx + 33.33);
  return fract((r.x + r.y) * r.x);
}
fn effect(px: vec2<f32>) -> vec4<f32> {
  let c = layer(px);
  if (c.a < 0.001) { return c; }
  let k = u.w / 1080.0;
  let n = h21(floor(px / max(k * 1.3, 0.5)) + vec2<f32>(u.seed * 17.0, u.seed * 29.0));
  // a few pits in the line, never holes: the coating is a little thin in places
  let m = 1.0 - u.amount * smoothstep(0.55, 1.0, n);
  return c * m;
}
`;

/** One layer for a whole drawing: the strokes eroded a little (`chalk`, a new pattern on twos) and a halation. */
export const Ink: React.FC<{ id: string; children: React.ReactNode; chalk?: number; halo?: number; opacity?: number }> = ({ id, children, chalk = 0.25, halo = 0.55, opacity = 1 }) => {
  const f = useCurrentFrame();
  const { width: W } = useVideoConfig();
  const k = W / PAGE.w;
  return (
    <Layer id={id} opacity={opacity} effects={[shader({ code: CHALK, uniforms: { w: W, amount: chalk, seed: Math.floor(f / 2) % 7 } }), glow({ radius: 5 * k, intensity: halo })]}>
      <AbsoluteFill>{children}</AbsoluteFill>
    </Layer>
  );
};

/** A full-page svg in page px: children are drawn in page coordinates. */
const Page: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { width: W, height: H } = useVideoConfig();
  return (
    <svg width={W} height={H} viewBox={`0 0 ${PAGE.w} ${PAGE.h}`} style={{ position: 'absolute', left: 0, top: 0 }}>{children}</svg>
  );
};

const weight = (kind: Kind) => PEN[kind];
const speedOf = (kind: Kind) => (kind === 'object' ? PEN.objectSpeed : kind === 'thin' ? PEN.thinSpeed : PEN.hatchSpeed);

/** Frames a pen takes for a path at its kind's speed (at least 4): use it to chain strokes. */
export const penFrames = (d: string, kind: Kind = 'object', speed?: number) => Math.max(4, Math.ceil(getLength(d) / (speed ?? speedOf(kind))));

export interface StrokeProps {
  d: string;
  at: number;
  kind?: Kind;
  /** px per frame (the kind's pen speed by default) */
  speed?: number;
  color?: string;
  /** a frame from which it is gone (strokes are not erased; they just stop being drawn) */
  out?: number;
  /** show the pen's tip while it is moving */
  tip?: boolean;
  /** a fill drawn when the stroke ends (an arrow head) */
  fill?: string;
  opacity?: number;
}

/** A path drawn on by a pen: a trim from the start at constant speed. Its tip is a small bright dot. */
export const Stroke: React.FC<StrokeProps> = ({ d, at, kind = 'object', speed, color = BLUEPRINT.line, out, tip = false, fill, opacity = 1 }) => {
  const f = useCurrentFrame();
  if (f < at || (out !== undefined && f >= out)) return null;
  const len = getLength(d);
  const dur = penFrames(d, kind, speed);
  const k = clamp01((f - at + 1) / dur);
  const w = weight(kind);
  const p = tip && k < 1 ? getPointAtLength(d, len * k) : null;
  return (
    <Page>
      <path d={d} fill="none" stroke={color} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray="1 2" strokeDashoffset={1 - k} opacity={opacity} />
      {fill && k >= 1 && <path d={fill} fill={color} opacity={opacity} />}
      {p && <circle cx={p.x} cy={p.y} r={w * 1.5} fill={color} />}
    </Page>
  );
};

/** A dash-dot line from a to b (a centre line), drawn on at the thin pen's speed. `pattern` is dash, gap, dot, gap in px. */
export const CentreLine: React.FC<{ a: Pt; b: Pt; at: number; pattern?: [number, number, number, number]; speed?: number; color?: string }> = ({ a, b, at, pattern = [38, 9, 5, 9], speed, color = BLUEPRINT.dim }) => {
  const f = useCurrentFrame();
  if (f < at) return null;
  const L = Math.hypot(b[0] - a[0], b[1] - a[1]);
  const reach = Math.min(L, (f - at + 1) * (speed ?? PEN.thinSpeed * 1.4));
  const ux = (b[0] - a[0]) / L, uy = (b[1] - a[1]) / L;
  let s = '', pos = 0, i = 0;
  while (pos < reach) {
    const seg = pattern[i % 4]!;
    if (i % 2 === 0) {
      const e = Math.min(reach, pos + seg);
      s += `M${f2(a[0] + ux * pos)} ${f2(a[1] + uy * pos)}L${f2(a[0] + ux * e)} ${f2(a[1] + uy * e)}`;
    }
    pos += seg;
    i++;
  }
  return <Page><path d={s} fill="none" stroke={color} strokeWidth={PEN.thin} strokeLinecap="butt" /></Page>;
};

export const lineD = (a: Pt, b: Pt) => `M${f2(a[0])} ${f2(a[1])}L${f2(b[0])} ${f2(b[1])}`;
export const polyD = (pts: Pt[], close = false) => pts.map((p, i) => `${i ? 'L' : 'M'}${f2(p[0])} ${f2(p[1])}`).join('') + (close ? 'Z' : '');
export const rectD = (x: number, y: number, w: number, h: number) => polyD([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], true);
/** A circle as one path, starting at the top and running clockwise. */
export const circleD = (cx: number, cy: number, r: number) => `M${f2(cx)} ${f2(cy - r)}A${r} ${r} 0 1 1 ${f2(cx)} ${f2(cy + r)}A${r} ${r} 0 1 1 ${f2(cx)} ${f2(cy - r)}`;

/** 45 degree section lines (up and to the right) clipped to a rectangle, as one path of separate segments. */
export const hatchD = (x: number, y: number, w: number, h: number, gap = 14) => {
  let s = '';
  const step = gap * Math.SQRT2;
  for (let c = x + y + step / 2; c < x + w + y + h; c += step) {
    const lo = Math.max(x, c - (y + h)), hi = Math.min(x + w, c - y);
    if (hi - lo > 0.5) s += `M${f2(lo)} ${f2(c - lo)}L${f2(hi)} ${f2(c - hi)}`;
  }
  return s;
};

/** 45 degree section lines clipped to a convex polygon (a cut face), as one path of separate segments. */
export const hatchPolyD = (pts: Pt[], gap = 14) => {
  let s = '';
  const step = gap * Math.SQRT2;
  const sums = pts.map((p) => p[0] + p[1]);
  for (let c = Math.min(...sums) + step / 2; c < Math.max(...sums); c += step) {
    // the line x + y = c meets each edge where its parameter is in [0, 1]; the ends are the extremes along x
    const xs: number[] = [];
    pts.forEach((p, i) => {
      const q = pts[(i + 1) % pts.length]!;
      const d0 = p[0] + p[1] - c, d1 = q[0] + q[1] - c;
      if ((d0 <= 0 && d1 >= 0) || (d0 >= 0 && d1 <= 0)) {
        const t = d0 === d1 ? 0 : d0 / (d0 - d1);
        xs.push(p[0] + (q[0] - p[0]) * t);
      }
    });
    if (xs.length >= 2) {
      const lo = Math.min(...xs), hi = Math.max(...xs);
      if (hi - lo > 0.5) s += `M${f2(lo)} ${f2(c - lo)}L${f2(hi)} ${f2(c - hi)}`;
    }
  }
  return s;
};

/** A filled arrow head at `tip`, pointing along the unit vector (dx, dy). */
export const headD = (tip: Pt, dx: number, dy: number, len = 22, half = 6.5) => {
  const bx = tip[0] - dx * len, by = tip[1] - dy * len;
  return `M${f2(tip[0])} ${f2(tip[1])}L${f2(bx - dy * half)} ${f2(by + dx * half)}L${f2(bx + dy * half)} ${f2(by - dx * half)}Z`;
};

export interface DimProps {
  /** the two points being measured, on the object */
  a: Pt;
  b: Pt;
  /** distance from the object to the dimension line, px, signed (which side) */
  off: number;
  text: string;
  at: number;
  /** rotate the figure (a vertical dimension reads from the right at -90) */
  textRot?: number;
  size?: number;
}

/** A dimension: two extension lines, a dimension line with a head at each end and a gap for the figure, which types in. */
export const Dim: React.FC<DimProps> = ({ a, b, off, text, at, textRot = 0, size = 30 }) => {
  const f = useCurrentFrame();
  const L = Math.hypot(b[0] - a[0], b[1] - a[1]);
  const ux = (b[0] - a[0]) / L, uy = (b[1] - a[1]) / L;
  const s = off >= 0 ? 1 : -1;
  const nx = -uy * s, ny = ux * s, o = Math.abs(off);
  const at1: Pt = [a[0] + nx * o, a[1] + ny * o], at2: Pt = [b[0] + nx * o, b[1] + ny * o];
  const ext1 = lineD([a[0] + nx * 10, a[1] + ny * 10], [at1[0] + nx * 14, at1[1] + ny * 14]);
  const ext2 = lineD([b[0] + nx * 10, b[1] + ny * 10], [at2[0] + nx * 14, at2[1] + ny * 14]);
  const mid: Pt = [(at1[0] + at2[0]) / 2, (at1[1] + at2[1]) / 2];
  // a short dimension keeps its line whole and puts the figure beside it; a long one opens a gap for the figure
  const tight = text.length * size * 0.62 + 70 > L;
  const half = tight ? 0 : (text.length * size * 0.62) / 2 + 12;
  const g1: Pt = tight ? at1 : [mid[0] - ux * half, mid[1] - uy * half], g2: Pt = tight ? at2 : [mid[0] + ux * half, mid[1] + uy * half];
  const t0 = at + penFrames(ext1, 'thin');
  const d1 = tight ? lineD(at1, at2) : lineD(at1, g1), d2 = lineD(at2, g2);
  const t1 = t0 + penFrames(d1, 'thin', PEN.thinSpeed * 1.4);
  const pop = outCubic((f - t0) / 4);
  const popped = (tip: Pt, dx: number, dy: number) => headD([tip[0], tip[1]], dx, dy, 22 * pop, 6.5 * pop);
  const tx = tight ? mid[0] + nx * (size * 0.95 + 6) : mid[0], ty = tight ? mid[1] + ny * (size * 0.95 + 6) : mid[1];
  return (
    <>
      <Stroke d={ext1} at={at} kind="thin" color={BLUEPRINT.dim} />
      <Stroke d={ext2} at={at} kind="thin" color={BLUEPRINT.dim} />
      <Stroke d={d1} at={t0} kind="thin" speed={PEN.thinSpeed * 1.4} />
      {!tight && <Stroke d={d2} at={t0} kind="thin" speed={PEN.thinSpeed * 1.4} />}
      {f >= t0 && pop > 0 && (
        <Page>
          <path d={popped(at1, -ux, -uy)} fill={BLUEPRINT.line} />
          <path d={popped(at2, ux, uy)} fill={BLUEPRINT.line} />
        </Page>
      )}
      <Typed text={text} x={tx} y={ty} size={size} at={t1} align="center" face="figure" rot={textRot} />
    </>
  );
};

/** The faint printed grid under a drawing: a coarse and a fine pitch, drawn static at low alpha. */
export const Grid: React.FC<{ at?: number; fade?: number; major?: number; minor?: number; opacity?: number }> = ({ at = 0, fade = 20, major = 135, minor = 27, opacity = 1 }) => {
  const f = useCurrentFrame();
  const k = clamp01((f - at) / fade) * opacity;
  if (k <= 0) return null;
  const lines = (pitch: number) => {
    let s = '';
    for (let x = 0; x <= PAGE.w; x += pitch) s += `M${x} 0V${PAGE.h}`;
    for (let y = 0; y <= PAGE.h; y += pitch) s += `M0 ${y}H${PAGE.w}`;
    return s;
  };
  return (
    <Page>
      <path d={lines(minor)} stroke={BLUEPRINT.dim} strokeWidth={1} opacity={0.07 * k} fill="none" />
      <path d={lines(major)} stroke={BLUEPRINT.dim} strokeWidth={1.6} opacity={0.16 * k} fill="none" />
    </Page>
  );
};

/** A detail callout: a circle drawn round a place, a leader line and its letter. */
export const Callout: React.FC<{ cx: number; cy: number; r: number; letter: string; at: number; leader?: Pt; color?: string }> = ({ cx, cy, r, letter, at, leader = [cx + r * 1.7, cy - r * 1.7], color = BLUEPRINT.line }) => {
  const c = circleD(cx, cy, r);
  const t = at + penFrames(c, 'thin', 70);
  const ang = Math.atan2(leader[1] - cy, leader[0] - cx);
  const start: Pt = [cx + Math.cos(ang) * r, cy + Math.sin(ang) * r];
  const lead = lineD(start, leader);
  const t2 = t + penFrames(lead, 'thin');
  const bubble = circleD(leader[0] + Math.cos(ang) * 34, leader[1] + Math.sin(ang) * 34, 34);
  return (
    <>
      <Stroke d={c} at={at} kind="thin" speed={70} color={color} />
      <Stroke d={lead} at={t} kind="thin" color={color} />
      <Stroke d={bubble} at={t2} kind="thin" speed={70} color={color} />
      <Typed text={letter} x={leader[0] + Math.cos(ang) * 34} y={leader[1] + Math.sin(ang) * 34} size={44} at={t2 + 6} align="center" face="label" weight={600} />
    </>
  );
};

/** The drawing sheet's border: a thin rule inset from the edge, with a tick at every quarter, drawn by the pen. */
export const Border: React.FC<{ at: number; inset?: number }> = ({ at, inset = 52 }) => {
  const x0 = inset, y0 = inset, x1 = PAGE.w - inset, y1 = PAGE.h - inset;
  const frame = rectD(x0, y0, x1 - x0, y1 - y0);
  const ticks = [1, 2, 3].map((i) => {
    const x = x0 + ((x1 - x0) * i) / 4, y = y0 + ((y1 - y0) * i) / 4;
    return lineD([x, y0], [x, y0 + 16]) + lineD([x, y1], [x, y1 - 16]) + lineD([x0, y], [x0 + 16, y]) + lineD([x1, y], [x1 - 16, y]);
  }).join('');
  const t = at + penFrames(frame, 'thin', 130);
  return (
    <>
      <Stroke d={frame} at={at} kind="thin" speed={130} color={BLUEPRINT.dim} />
      <Stroke d={ticks} at={t} kind="thin" speed={200} color={BLUEPRINT.dim} />
    </>
  );
};

// What the camera and the lamp do over a drawing:
//   Push        a slow push in about a pivot, eased, never a shake (about 0.0007 a frame)
//   Flash       the exposure lamp coming on: a pale cyan screen at the start that falls away in 10 frames
//   DetailIris  the taste's cut: a circle opens from a callout and the next sheet fills it (22 frames, eased in and out),
//               a thin ring riding its edge
import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { BLUEPRINT, PAGE } from './tokens.js';

const clamp01 = (t: number) => Math.min(1, Math.max(0, t));
const inOutCubic = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);

export const Push: React.FC<{ from?: number; to: number; at: number; dur: number; pivot?: [number, number]; children: React.ReactNode }> = ({ from = 1, to, at, dur, pivot = [0.5, 0.5], children }) => {
  const f = useCurrentFrame();
  const t = inOutCubic(clamp01((f - at) / dur));
  const s = from + (to - from) * t;
  return <AbsoluteFill style={{ transform: `scale(${s.toFixed(5)})`, transformOrigin: `${pivot[0] * 100}% ${pivot[1] * 100}%` }}>{children}</AbsoluteFill>;
};

export const Flash: React.FC<{ at?: number; dur?: number }> = ({ at = 0, dur = 10 }) => {
  const f = useCurrentFrame();
  const a = 1 - clamp01((f - at) / dur);
  if (a <= 0) return null;
  return <AbsoluteFill style={{ background: '#cfeaff', opacity: 0.8 * a * a, mixBlendMode: 'screen' }} />;
};

export interface DetailIrisProps {
  /** the circle's centre in page px, and the radius it starts from (the callout's) */
  cx: number;
  cy: number;
  r0: number;
  at: number;
  dur?: number;
  before: React.ReactNode;
  after: React.ReactNode;
}

export const DetailIris: React.FC<DetailIrisProps> = ({ cx, cy, r0, at, dur = 22, before, after }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const k = W / PAGE.w;
  const t = clamp01((f - at) / dur);
  if (t <= 0) return <>{before}</>;
  const far = Math.hypot(Math.max(cx, PAGE.w - cx), Math.max(cy, PAGE.h - cy)) + 20;
  const r = (r0 + (far - r0) * inOutCubic(t)) * k;
  if (t >= 1) return <>{after}</>;
  return (
    <>
      {before}
      <AbsoluteFill style={{ clipPath: `circle(${r.toFixed(1)}px at ${(cx * k).toFixed(1)}px ${(cy * k).toFixed(1)}px)` }}>{after}</AbsoluteFill>
      <svg width={W} height={H} style={{ position: 'absolute', left: 0, top: 0 }}>
        <circle cx={cx * k} cy={cy * k} r={r} fill="none" stroke={BLUEPRINT.line} strokeWidth={3 * k} opacity={1 - t * 0.6} />
      </svg>
    </>
  );
};

// The blueprint taste: a technical drawing on a cyanotype sheet. See tokens.ts for the rules and TASTE.md for when to use it.
export { BLUEPRINT, FONTS, PAGE, PEN } from './tokens.js';
export { Sheet } from './sheet.js';
export { Border, Callout, CentreLine, Dim, Grid, Ink, Stroke, circleD, hatchD, hatchPolyD, headD, lineD, penFrames, polyD, rectD } from './draw.js';
export type { DimProps, Kind, Pt, StrokeProps } from './draw.js';
export { PageBox, Plot, Stamp, Typed, family } from './type.js';
export type { PlotProps, StampProps, TypedProps } from './type.js';
export { TitleBlock } from './block.js';
export type { Cell } from './block.js';
export { DetailIris, Flash, Push } from './finish.js';
export { Cyanotype } from './photo.js';

// The picture treatment: a photograph printed as a cyanotype. Its tones are mapped through a gradient from the
// coating's deep blue to a pale blue-white (a gradient map in blue, never a tint over colour), with the contrast
// raised a little and a soft halation in the lights. Wrap any picture or video; it fills the page.
import React from 'react';
import { Layer, contrast, gradientMap, glow } from '@kinetographdev/core';
import { AbsoluteFill } from 'remotion';
import { BLUEPRINT } from './tokens.js';

export const Cyanotype: React.FC<{ id: string; children: React.ReactNode; contrast?: number; halo?: number }> = ({ id, children, contrast: c = 1.15, halo = 0.25 }) => (
  <Layer id={id} effects={[
    contrast(c),
    gradientMap({ stops: [{ offset: 0, color: '#04152e' }, { offset: 0.35, color: BLUEPRINT.deep }, { offset: 0.7, color: '#4f8fd0' }, { offset: 1, color: '#e9f4ff' }] }),
    glow({ radius: 6, intensity: halo }),
  ]}>
    <AbsoluteFill>{children}</AbsoluteFill>
  </Layer>
);

// The cyanotype sheet, made live by one shader (no scanned texture): a brushed coating of Prussian blue with
//   - slow mottling (uneven coating) and horizontal brush streaks
//   - a thin, wobbling band at the edge where the brush stopped: the coating thins to a pale blue, then bare paper
//   - paper fibres, a vertical and a horizontal fold crease (a lighter line with a darker lip), a soft vignette
// The grain is a hash of the pixel and `seed`; the reel re-rolls it on twos so the sheet crawls a little, as a
// contact print under a lamp does.
import React from 'react';
import { Layer, Rect, shader } from '@kinetographdev/core';
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from 'remotion';
import { BLUEPRINT } from './tokens.js';

const SHEET = /* wgsl */ `
fn h21(p: vec2<f32>) -> f32 {
  let q = fract(p * vec2<f32>(0.1031, 0.1030));
  let r = q + dot(q, q.yx + 33.33);
  return fract((r.x + r.y) * r.x);
}
fn vn(p: vec2<f32>) -> f32 {
  let i = floor(p); let f = fract(p);
  let s = f * f * (3.0 - 2.0 * f);
  return mix(mix(h21(i), h21(i + vec2<f32>(1.0, 0.0)), s.x), mix(h21(i + vec2<f32>(0.0, 1.0)), h21(i + vec2<f32>(1.0, 1.0)), s.x), s.y);
}
fn fbm(p: vec2<f32>) -> f32 {
  var a = 0.5; var q = p; var t = 0.0;
  for (var i = 0; i < 4; i++) { t += a * vn(q); q = q * 2.03 + vec2<f32>(17.1, 9.7); a *= 0.5; }
  return t;
}
fn toLin(c: f32) -> f32 { return select(pow((c + 0.055) / 1.055, 2.4), c / 12.92, c <= 0.04045); }

fn effect(px: vec2<f32>) -> vec4<f32> {
  let k = u.w / 1080.0;
  let p = px / k;                       // page px at 1080 wide
  let sd = vec2<f32>(u.seed * 13.7, u.seed * 7.3);
  let deep = vec3<f32>(u.dr, u.dg, u.db);
  let mid = vec3<f32>(u.mr, u.mg, u.mb);
  let lit = vec3<f32>(u.lr, u.lg, u.lb);
  let pap = vec3<f32>(u.pr, u.pg, u.pb);

  // coating density: slow mottling plus horizontal brush strokes (long in x, thin in y)
  let mott = fbm(p / 330.0 + 3.1);
  let rp = vec2<f32>(p.x * 0.998 + p.y * 0.06, p.y);
  let streak = vn(vec2<f32>(rp.x / 760.0, rp.y / 11.0) + 5.0) * 0.6 + vn(vec2<f32>(rp.x / 300.0, rp.y / 3.5) + 9.0) * 0.4;
  var d = 0.22 + 0.55 * mott + 0.16 * (streak - 0.5);
  // fibres: fine, slightly stretched noise darkens and lightens the coating
  let fib = vn(vec2<f32>(p.x / 1.1, p.y / 2.6) + sd) * 0.6 + h21(floor(p * 0.9) + sd) * 0.4;
  d += (fib - 0.5) * 0.10;
  d = clamp(d, 0.0, 1.0);
  var col = mix(deep, mid, smoothstep(0.15, 0.75, d));
  col = mix(col, lit, smoothstep(0.72, 1.0, d) * 0.55);

  // the brushed edge: distance to the sheet's edge, pushed in and out by noise
  let ed = min(min(p.x, 1080.0 - p.x), min(p.y, 1920.0 - p.y));
  let wob = (fbm(p / 55.0 + 21.0) - 0.5) * 26.0 + (streak - 0.5) * 12.0;
  let e = ed + wob;
  let thin = 1.0 - smoothstep(10.0, 46.0, e);       // coating thinning toward the edge
  col = mix(col, lit * 1.2, thin * 0.5);
  let bare = 1.0 - smoothstep(5.0, 11.0, e);        // bare paper past the brush
  col = mix(col, pap, bare);

  // folds: one down the middle, one across, a lighter line with a darker lip beside it
  let fx = abs(p.x - 540.0 + (vn(vec2<f32>(p.y / 90.0, 2.0)) - 0.5) * 6.0);
  let fy = abs(p.y - 960.0 + (vn(vec2<f32>(p.x / 90.0, 4.0)) - 0.5) * 6.0);
  let crease = max(1.0 - smoothstep(0.0, 2.0, min(fx, fy)), 0.0);
  let lip = max(1.0 - smoothstep(2.0, 6.0, min(fx, fy)), 0.0) - crease;
  col = col + crease * 0.07 * vec3<f32>(0.55, 0.8, 1.0) - lip * 0.03;

  // vignette
  let c = (px / vec2<f32>(u.w, u.h)) - 0.5;
  col = mix(col * (1.0 - u.vig * dot(c, c) * 1.6), col, bare);
  col = col * u.expo;

  let o = clamp(col, vec3<f32>(0.0), vec3<f32>(1.0));
  return vec4<f32>(toLin(o.r), toLin(o.g), toLin(o.b), 1.0);
}
`;

const disp = (hex: string) => { const n = parseInt(hex.replace('#', ''), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255] as const; };

export interface SheetProps {
  /** frames per grain pattern (2: on twos) */
  hold?: number;
  /** vignette strength 0..1 */
  vignette?: number;
  /** exposure multiplier (above 1 is the flash of the lamp) */
  exposure?: number;
  /** a number that changes the brush pattern (a different sheet) */
  seed?: number;
}

export const Sheet: React.FC<SheetProps> = ({ hold = 2, vignette = 0.55, exposure = 1, seed = 1 }) => {
  const f = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();
  const [dr, dg, db] = disp(BLUEPRINT.deep), [mr, mg, mb] = disp(BLUEPRINT.mid), [lr, lg, lb] = disp(BLUEPRINT.light), [pr, pg, pb] = disp(BLUEPRINT.paper);
  return (
    <AbsoluteFill>
      <Layer id={`bp-sheet-${seed}`} effects={[shader({ code: SHEET, uniforms: { dr, dg, db, mr, mg, mb, lr, lg, lb, pr, pg, pb, w: W, h: H, vig: vignette, expo: exposure, seed: seed * 3 + (Math.floor(f / hold) % 5) * 0.015 } })]}>
        <Rect width={W} height={H} fill="#ffffff" />
      </Layer>
    </AbsoluteFill>
  );
};

// The blueprint taste: a technical drawing on a cyanotype sheet. White lines draw themselves on Prussian blue, with
// dimension lines, section hatching, typed labels, a title block and one red revision stamp. Original to this repo:
// nothing here is read off a reel, so every number is a design choice, written down so another reel can reuse it
// (taste.json holds the same values).
//
// Rules every component follows:
//   - the sheet is blue, the drawing is light; the only other colour is the redline stamp
//   - lines are drawn at a constant pen speed, never faded in: object lines 30 px/f, thin lines 46 px/f (1080 wide)
//   - three line weights: object 5.5 px, thin 2.4 px, hatch 1.6 px; a centre line is dash-dot, thin
//   - every light mark has a faint halation (a soft glow), as an overexposed print does; nothing casts a shadow
//   - labels type on a character a frame behind a plotter caret; one text move at a time
//   - the camera only pushes (about 0.0007 a frame) and never shakes; cuts are a flash or a circular detail iris
//   - fonts: Barlow Condensed (labels, titles, stamps) and IBM Plex Mono (figures), both SIL OFL 1.1

export const BLUEPRINT = {
  /** the cyanotype: deep, mid and light blue of the coating, and the unexposed paper at the brushed edge */
  deep: '#0a2a55',
  mid: '#12427f',
  light: '#2468b0',
  paper: '#e6eef2',
  /** the drawing: a white with a cool cast, and a dimmer one for thin lines and the grid */
  line: '#f2f8ff',
  dim: '#a9c8e8',
  /** the one accent: a revision-stamp red */
  redline: '#ff6a4d',
} as const;

export const FONTS = {
  /** titles, labels, stamps */
  label: 'Barlow Condensed',
  /** dimensions, figures, notes */
  figure: 'IBM Plex Mono',
} as const;

/** Line weights at 1080 px wide, and the pen speeds in px per frame. */
export const PEN = { object: 5.5, thin: 2.4, hatch: 1.6, objectSpeed: 30, thinSpeed: 46, hatchSpeed: 120 } as const;

/** The page every component draws on: 1080 x 1920. Components take page px and scale to the composition. */
export const PAGE = { w: 1080, h: 1920 } as const;

// Type in the blueprint taste, one move at a time:
//   Typed      a plotter types a label a character about every frame (a fast line, 1.4 a frame) behind a small
//              caret block that stays a few frames after the last letter
//   Plot       a big title swept in by the plotter carriage: a thin bright bar moves left to right at 54 px a frame
//              and the letters stay behind it
//   Stamp      a red rubber stamp: lands from 1.7x in 5 frames (eased out), full alpha in 2, a little uneven ink
//   TitleBlock the sheet's corner table: its frame and rules are drawn by the pen, then the cells type in
// All sizes are page px (1080 wide). The faces are Barlow Condensed and IBM Plex Mono (SIL OFL 1.1).
import React from 'react';
import { Layer, glow, shader } from '@kinetographdev/core';
import { makeGoogleFont } from '@kinetographdev/core/google-fonts';
import { useCurrentFrame, useVideoConfig } from 'remotion';
import { BLUEPRINT, FONTS, PAGE, PEN } from './tokens.js';

const clamp01 = (t: number) => Math.min(1, Math.max(0, t));
const outCubic = (t: number) => 1 - (1 - clamp01(t)) ** 3;

const loaded = new Map<string, string>();
/** The font-family string for a Google font at a weight (loaded once). */
export function family(name: string, weight: number): string {
  const key = `${name}|${weight}`;
  let fam = loaded.get(key);
  if (!fam) {
    try { fam = makeGoogleFont(name.replace(/ /g, '')).loadFont('normal', { weights: [String(weight)] }).fontFamily; }
    catch { fam = name; }
    loaded.set(key, fam);
  }
  return fam;
}

/** A box in page px (1080 x 1920) scaled to the composition: children use page px. */
export const PageBox: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { width: W } = useVideoConfig();
  return <div style={{ position: 'absolute', left: 0, top: 0, width: PAGE.w, height: PAGE.h, transform: `scale(${W / PAGE.w})`, transformOrigin: '0 0' }}>{children}</div>;
};

type Face = 'label' | 'figure';
const faceStyle = (face: Face, weight: number): React.CSSProperties => ({ fontFamily: family(face === 'label' ? FONTS.label : FONTS.figure, weight), fontWeight: weight });

export interface TypedProps {
  text: string;
  /** anchor in page px: the left edge, centre or right edge of the line, and its vertical centre */
  x: number;
  y: number;
  size: number;
  at: number;
  align?: 'left' | 'center' | 'right';
  face?: Face;
  weight?: number;
  color?: string;
  /** characters a frame */
  cps?: number;
  tracking?: number;
  rot?: number;
  /** a frame from which the line is gone */
  out?: number;
  caret?: boolean;
}

export const Typed: React.FC<TypedProps> = ({ text, x, y, size, at, align = 'left', face = 'figure', weight, color = BLUEPRINT.line, cps = 1.4, tracking, rot = 0, out, caret = true }) => {
  const f = useCurrentFrame();
  if (f < at || (out !== undefined && f >= out)) return null;
  const n = Math.min(text.length, Math.floor((f - at + 1) * cps));
  const typing = n < text.length || f - at < text.length / cps + 6;
  const w = weight ?? (face === 'label' ? 500 : 500);
  const tr = tracking ?? (face === 'label' ? 0.06 : 0);
  const tx = align === 'left' ? '0' : align === 'center' ? '-50%' : '-100%';
  return (
    <PageBox>
      <div style={{ position: 'absolute', left: x, top: y, transform: `translate(${tx}, -50%) rotate(${rot}deg)`, whiteSpace: 'nowrap', fontSize: size, lineHeight: 1, letterSpacing: `${tr}em`, color, ...faceStyle(face, w) }}>
        <span>{text.slice(0, n)}</span>
        {caret && typing && <span style={{ display: 'inline-block', width: 0, position: 'relative' }}><span style={{ position: 'absolute', left: size * 0.06, top: -size * 0.42, width: size * 0.34, height: size * 0.84, background: color, opacity: 0.9 }} /></span>}
        <span style={{ opacity: 0 }}>{text.slice(n)}</span>
      </div>
    </PageBox>
  );
};

export interface PlotProps {
  lines: string[];
  x: number;
  /** the vertical centre of the first line, and the line pitch (px) */
  y: number;
  size: number;
  at: number;
  pitch?: number;
  /** px a frame the carriage moves */
  speed?: number;
  /** frames between lines */
  stagger?: number;
  weight?: number;
  color?: string;
  tracking?: number;
  out?: number;
}

export const Plot: React.FC<PlotProps> = ({ lines, x, y, size, at, pitch = size * 0.92, speed = 54, stagger = 8, weight = 700, color = BLUEPRINT.line, tracking = 0.035, out }) => {
  const f = useCurrentFrame();
  if (out !== undefined && f >= out) return null;
  return (
    <PageBox>
      {lines.map((line, i) => {
        const t = f - (at + i * stagger);
        if (t < 0) return null;
        const reach = Math.min(PAGE.w - x, (t + 1) * speed) ;
        const done = reach >= PAGE.w - x;
        return (
          <div key={i} style={{ position: 'absolute', left: x, top: y + i * pitch - size * 0.55, width: reach, height: size * 1.1, overflow: 'hidden' }}>
            <div style={{ position: 'absolute', left: 0, top: size * 0.55, transform: 'translateY(-50%)', whiteSpace: 'nowrap', fontSize: size, lineHeight: 1, letterSpacing: `${tracking}em`, color, ...faceStyle('label', weight) }}>{line}</div>
            {!done && <div style={{ position: 'absolute', right: 0, top: 0, width: 4, height: '100%', background: BLUEPRINT.line, boxShadow: `0 0 18px ${BLUEPRINT.line}` }} />}
          </div>
        );
      })}
    </PageBox>
  );
};

const STAMP = /* wgsl */ `
fn h21(p: vec2<f32>) -> f32 {
  let q = fract(p * vec2<f32>(0.1031, 0.1030));
  let r = q + dot(q, q.yx + 33.33);
  return fract((r.x + r.y) * r.x);
}
fn vn(p: vec2<f32>) -> f32 {
  let i = floor(p); let f = fract(p);
  let s = f * f * (3.0 - 2.0 * f);
  return mix(mix(h21(i), h21(i + vec2<f32>(1.0, 0.0)), s.x), mix(h21(i + vec2<f32>(0.0, 1.0)), h21(i + vec2<f32>(1.0, 1.0)), s.x), s.y);
}
fn effect(px: vec2<f32>) -> vec4<f32> {
  let c = layer(px);
  if (c.a < 0.001) { return c; }
  let k = u.w / 1080.0;
  let n = h21(floor(px / (1.4 * k)) + 3.0) * 0.45 + vn(px / (9.0 * k) + 11.0) * 0.55;
  // uneven rubber: patches of thin ink and pin-holes
  let m = mix(0.42, 1.0, smoothstep(0.30, 0.58, n));
  return c * m;
}
`;

export interface StampProps {
  text: string;
  x: number;
  y: number;
  size: number;
  at: number;
  /** degrees */
  rot?: number;
  color?: string;
  /** a second smaller line inside the box (a date, a reference) */
  sub?: string;
  out?: number;
}

export const Stamp: React.FC<StampProps> = ({ text, x, y, size, at, rot = -6, color = BLUEPRINT.redline, sub, out }) => {
  const f = useCurrentFrame();
  const { width: W } = useVideoConfig();
  if (f < at || (out !== undefined && f >= out)) return null;
  const t = (f - at + 1) / 5;
  const sc = 1 + 0.7 * (1 - outCubic(t));
  const a = clamp01((f - at + 1) / 2);
  const pad = size * 0.28;
  return (
    <Layer id={`stamp-${text}-${at}`} opacity={a} effects={[shader({ code: STAMP, uniforms: { w: W } }), glow({ radius: 2.2 * (W / PAGE.w), intensity: 0.4 })]}>
      <PageBox>
        <div style={{ position: 'absolute', left: x, top: y, transform: `translate(-50%, -50%) rotate(${rot}deg) scale(${sc})`, whiteSpace: 'nowrap', textAlign: 'center', color, padding: `${pad * 0.7}px ${pad * 1.2}px`, border: `${Math.max(5, size * 0.055)}px solid ${color}`, borderRadius: size * 0.07, boxShadow: `inset 0 0 0 ${Math.max(2, size * 0.02)}px transparent, 0 0 0 ${Math.max(3, size * 0.03)}px ${color}33`, ...faceStyle('label', 800), fontSize: size, lineHeight: 1, letterSpacing: '0.07em' }}>
          {text}
          {sub && <div style={{ ...faceStyle('figure', 600), fontSize: size * 0.2, letterSpacing: '0.12em', marginTop: size * 0.12 }}>{sub}</div>}
        </div>
      </PageBox>
    </Layer>
  );
};
